//! The language server's field catalog generated from the Rust models
//! against the one the oracle generates (`lsp_catalog.py`): the catalog the
//! engine compiles in (`data/catalogs/tide/generated/`), generated by the
//! oracle from the bundled configuration with no workspace objects, which is
//! what `opentide generate schemas` writes in a workspace with no
//! configuration of its own (the `empty` fixture's golden recordings). The
//! bytes must be the same, the `opentide` label set to the oracle's version.

#![expect(
    clippy::unwrap_used,
    reason = "test helpers outside #[test]: a missing file or a malformed row fails the test"
)]

use std::path::{Path, PathBuf};
use std::sync::Arc;

use opentide_schema::configuration::resolve::{Instance, resolve};
use opentide_schema::generate::catalog::{DEPRECATIONS_FILE, FIELDS_FILE, catalog_texts};
use opentide_schema::generate::schema::Sources;
use opentide_schema::vocab::Vocabularies;
use serde_json::Value;

fn repo() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn bundled_sources() -> Sources {
    let resolved = resolve(&Instance {
        skip_parent: true,
        ..Instance::default()
    })
    .unwrap();
    Sources {
        config: Arc::new(resolved.tree),
        vocabularies: Arc::new(Vocabularies::bundled()),
    }
}

/// The rows of a `fields.json` by schema and path; the labels left out.
fn rows(document: &Value) -> Vec<(String, Value)> {
    document["fields"]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| {
            (
                format!(
                    "{} {}",
                    row["schema"].as_str().unwrap(),
                    row["path"].as_str().unwrap()
                ),
                row.clone(),
            )
        })
        .collect()
}

#[test]
fn the_catalog_is_the_oracles() {
    let dir = repo().join("data/catalogs/tide/generated");
    let fields = std::fs::read_to_string(dir.join(FIELDS_FILE)).unwrap();
    let label: Value = serde_json::from_str(&fields).unwrap();
    let version = label["opentide"].as_str().unwrap();
    let texts = catalog_texts(version, &bundled_sources());
    let mut problems = Vec::new();
    for (name, text) in &texts {
        let expected = std::fs::read_to_string(dir.join(name)).unwrap();
        if *text == expected {
            continue;
        }
        let mut ours: Value = serde_json::from_str(text).unwrap();
        let mut theirs: Value = serde_json::from_str(&expected).unwrap();
        for document in [&mut ours, &mut theirs] {
            document.as_object_mut().unwrap().remove("opentide");
        }
        if *name == FIELDS_FILE {
            let (ours_rows, theirs_rows) = (rows(&ours), rows(&theirs));
            let ours_keys: Vec<&String> = ours_rows.iter().map(|(key, _)| key).collect();
            let theirs_keys: Vec<&String> = theirs_rows.iter().map(|(key, _)| key).collect();
            for key in &theirs_keys {
                if !ours_keys.contains(key) {
                    problems.push(format!("missing row {key}"));
                }
            }
            for key in &ours_keys {
                if !theirs_keys.contains(key) {
                    problems.push(format!("extra row {key}"));
                }
            }
            for (key, row) in &ours_rows {
                if let Some((_, other)) = theirs_rows.iter().find(|(k, _)| k == key)
                    && row != other
                {
                    let fields: Vec<String> = row
                        .as_object()
                        .unwrap()
                        .keys()
                        .chain(other.as_object().unwrap().keys())
                        .filter(|field| row.get(*field) != other.get(*field))
                        .map(|field| {
                            let show = |v: Option<&Value>| {
                                let text = v.map_or("(absent)".to_owned(), Value::to_string);
                                text.chars().take(160).collect::<String>()
                            };
                            format!(
                                "{field}: ours {} theirs {}",
                                show(row.get(field)),
                                show(other.get(field))
                            )
                        })
                        .collect();
                    problems.push(format!("{key}: {}", fields.join("; ")));
                }
            }
            for key in ["ref_leaves", "schemas", "generator"] {
                if ours[key] != theirs[key] {
                    problems.push(format!("{key}: ours {} theirs {}", ours[key], theirs[key]));
                }
            }
        } else if ours != theirs {
            problems.push(format!("{DEPRECATIONS_FILE}: ours {ours} theirs {theirs}"));
        }
    }
    if problems.is_empty()
        && texts
            .iter()
            .any(|(name, text)| std::fs::read_to_string(dir.join(name)).unwrap() != *text)
    {
        problems.push("the documents agree but their bytes differ".to_owned());
    }
    problems.dedup();
    assert!(
        problems.is_empty(),
        "{} difference(s):\n{}",
        problems.len(),
        problems.join("\n")
    );
}
